/* WHOLE_DRIVER_CANDIDATE fn_0000000000015680 origin=model_output original=disable_all_frame_buffers */
int32_t disable_all_frame_buffers(void)
{
    int32_t val = APICAL_READ_32(0x2c0);
    APICAL_WRITE_32(0x2c0, val & 0xfffffffe);
    val = APICAL_READ_32(0xa00);
    return APICAL_WRITE_32(0xa00, val & 0xfffeffff);
}

