			int32_t field_5c = *(int32_t *)((char *)arg1 + 0x5c);
			uint32_t reg;

			APICAL_WRITE_32(0x24c,
				(APICAL_READ_32(0x24c) & 0xfffff000) |
				(field_5c & 0xfff));
