	AWB_fsm_clear((uintptr_t)(base + 0x748));

	*(uint32_t *)(base + 0xeec) = 4;
	*(void **)(base + 0xee8) = base;
	color_matrix_fsm_clear(base + 0xee8);

	*(uint32_t *)(base + 0xfd8) = 4;
	*(void **)(base + 0xfd4) = base;
	iridix_fsm_clear(base + 0xfd4);

