    int32_t val_2cc = *(int32_t *)((char *)ctx + 0x2cc);
    int32_t val_2d0 = *(int32_t *)((char *)ctx + 0x2d0);
    int32_t val_2d4 = *(int32_t *)((char *)ctx + 0x2d4);
    int32_t reg_1d4 = APICAL_READ_32(0x1d4);
    int32_t reg_1cc = APICAL_READ_32(0x1cc);
